{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Safinamide absolute oral bioavailability was 95% (geometric mean AUC ratio vs IV) in healthy adults after a single 50 mg immediate-release tablet in the fasted state, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Sorafenib absolute oral bioavailability was 50% under fasted conditions, supporting F >= 20% despite other less direct low estimates.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Tofogliflozin absolute oral bioavailability was 97.5% in healthy male volunteers after a single 20 mg oral dose compared with IV microdosing, supporting F >= 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred evidence molecules support F >= 20% when prioritizing numeric absolute or fasted-state measurements; representative values range from about 50% to 97.5%, and the lowest strong absolute value (drotaverine 24.5%) remains above the threshold. Conflicting low reports come from less direct methods or altered formulations/populations.",
  "evidence_gaps": [
    "Fasted-state absolute bioavailability data are limited; some supporting absolute values were obtained without explicit fed/fasted conditions.",
    "A few records report low oral bioavailability for sorafenib (~8.5%) and posaconazole suspension (16%) in altered formulations or special populations, but these are less direct than the fasted absolute values and do not change the molecule-level direction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

